import json, unicodedata
cards=[json.loads(l) for l in open('cards.jsonl')]
def add(i,word,breathing='none',accent='none',choice='literal',confidence='high',note='',overrides=None):
 c=cards[i]; ai=c['anchor_index']; letters=[]
 for ch in unicodedata.normalize('NFD',word):
  if unicodedata.category(ch).startswith('L'): letters.append([ch,[]])
  elif unicodedata.combining(ch) and letters: letters[-1][1].append(ch)
 def heads(m):
  return dict(breathing='dasia' if '\u0314' in m else 'psili' if '\u0313' in m else 'none',accent='circumflex' if '\u0342' in m else 'acute' if '\u0301' in m else 'grave' if '\u0300' in m else 'none',diaeresis='present' if '\u0308' in m else 'none',subscript='present' if '\u0345' in m else 'none')
 hs=[heads(m) for b,m in letters]
 hs[ai].update(breathing=breathing,accent=accent)
 for idx,vals in (overrides or {}).items(): hs[idx].update(vals)
 a=dict(card_id=c['card_id'],choice=choice,anchor_heads=hs[ai],letter_heads=[dict(index=j,**h) for j,h in enumerate(hs) if j!=ai],readability='readable',ownership_ok=True if any(x not in ['none','unknown'] for x in hs[ai].values()) else None,confidence=confidence,note=note,usage=dict(input_tokens=0,output_tokens=0))
 if choice=='literal':a['transcription']=word
 with open('answers.jsonl','a') as f:f.write(json.dumps(a,ensure_ascii=False)+'\n')
if __name__=='__main__':
 add(0,'ὧς','dasia','circumflex',note='Breathing below circumflex belongs to omega.')
 add(1,'ἶσόν','psili','unknown',confidence='medium',note='Dense merged initial mark; breathing appears smooth, upper accent uncertain.',overrides={})
 add(2,'οἷ','dasia','circumflex',note='Stacked breathing and circumflex over iota.')
 add(3,'εἷλκον','dasia','circumflex',note='Stacked breathing and circumflex over iota.')
 add(4,'αυτής',note='Alpha area is blank; acute is over eta.')
